import{_ as o,l as r,o as a,c as i,v as d,p,x as l,d as s,i as n,S as u}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"显影：搅拌与 puddle","description":"","frontmatter":{"title":"显影：搅拌与 puddle","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/develop-puddle.md","filePath":"litho/develop-puddle.md","lastUpdated":1789023840000}'),h={name:"litho/develop-puddle.md"};function c(_,e,E,m,f,A){const t=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=d('<h1 id="显影-搅拌与-puddle" tabindex="-1">显影：搅拌与 puddle <a class="header-anchor" href="#显影-搅拌与-puddle" aria-label="Permalink to &quot;显影：搅拌与 puddle&quot;">​</a></h1><div class="epigraph"><p>溶解速率曲线给出材料能走多快；轨道给出液膜是静止 puddle 还是流动更新。传质一变，CD 跟着变。</p><footer>—— 对照 Mack 溶解模型与轨道 puddle develop 公开流程</footer></div><p><a href="/litho/soft-bake">上一课</a>给出固体膜。主干已有 <a href="/litho/resist-contrast-curve">衬度曲线</a> 与 <a href="/litho/dissolution-mack">Mack 溶解</a>。缺口是实现：显影液怎么铺、停多久、要不要搅。本课钉 puddle 与搅拌，化学物种留给下一课 TMAH。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实验室喷淋与厂内 puddle 的边界层不同。静止 puddle 里溶解产物积累，局部 pH 与抑制剂浓度漂；旋转喷淋更新液体，但可能引入溅射缺陷。把所有 CD 偏差写成剂量，会漏掉这一段传质。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型正胶：喷嘴铺满 TMAH puddle，静止数秒至数十秒，再漂洗。时间是剂量之外的第二旋钮：过显影吃线宽，欠显影留残胶。搅拌（scan nozzle、轻微旋转）减薄边界层，加快到达体相速率。配方写清：铺液转速、puddle 时间、是否间歇旋转。</p>',7)),(a(),p(u,null,{default:l(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOLID%5B%22%E7%83%A4%E5%90%8E%E8%83%B6%22%5D%20--%3E%20PUD%5B%22%E9%93%BA%E6%B6%B2%20puddle%22%5D%0A%20%20PUD%20--%3E%20DISS%5B%22%E6%BA%B6%E8%A7%A3%20%2F%20%E4%BC%A0%E8%B4%A8%22%5D%0A%20%20DISS%20--%3E%20RINSE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%B2%E6%B4%97%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<p><span class="marginnote">EUV 薄胶的绝对溶解量小，但对残膜与残渣更敏感。同一 puddle 时间，DUV 厚胶与 EUV 薄胶不是同一个工艺窗口。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>溶解是表面反应加产物扩散。边界层厚，有效速率被扩散限制，衬度曲线的「实验室搅拌」假设失效。产物若抑制溶解，静止 puddle 会自减速——看起来像欠剂量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写负胶交联显影的溶剂体系细节。下一课钉 TMAH 浓度与表面活性剂，不改 puddle 运动学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>puddle 的传质与溶解曲线同样决定 CD。</li><li>搅拌与时间是轨道参数，不是扫描仪剂量的别名。</li><li>出处：Mack 溶解；轨道 puddle 通识。</li></ul>',7))])}const D=o(h,[["render",c]]);export{T as __pageData,D as default};
